// R2 holds the current Table of Contents (TOC) pointer

// INTER-MODULE CALL: Module A calls Func F (in Module B)

// 1. Caller Side (Module A)
CALL F_glink_stub  // Jump to linker-generated glue

// 2. Glink Stub (Handles linkage/TOC switch)
F_glink_stub:
    PUSH R2          // Save CallerTOC (A)
    LOAD R2, TOC_B   // Load CalleeTOC (B)
    JUMP F_RealEntry // Direct branch to function body

// 3. Callee Entry (Module B)
F_RealEntry:
    // Func F executes using R2=TOC_B
    POP R2           // Restore CallerTOC (A)
    RETURN           // Return to caller in Module A
